"""Content of RADION_SYMBOLS (Markdown + LaTeX): every symbol used in the document on the radion of 7+1 spacetime, with its definition and
its Mathematica name in 7+1.nb (section 26 and the earlier sections it uses).  Self-contained: every equation needed to define a symbol is
written here."""
from docgen import Doc
from doc_common import signature_block

W4 = [0.17, 0.22, 0.31, 0.30]
HEAD4 = ['symbol', 'Mathematica', 'definition', 'meaning']


def build(D, today):
    d = Doc('The radion of 7+1 spacetime: symbols and their definitions',
            'A dictionary of every symbol used in the document on the radion, with its defining equation and its name in the notebook 7+1.nb',
            ['Repository: github.com/once-ere/7plus1 — prepared for Nash',
             'Notebook: 7+1.nb (Wolfram Language 15.0.1)',
             'Document generated by tools/make_docs.py on ' + today],
            'For each symbol this dictionary gives the mathematical notation, the name used in the Mathematica notebook 7+1.nb (where there is '
            'one; the names of section 26 begin with `rd`; "—" means that the notebook has no separate name), the defining equation and its '
            'meaning, grouped by topic in the order of the document. Longer defining equations follow each table as numbered displayed formulas. '
            'Section 11 lists the symbols that look alike, section 12 every Mathematica name of section 26. Every equation needed to define a '
            'symbol is written in this document.')

    # ------------------------------------------------------------------------------------------------
    d.h1('1. Conventions')
    d.ul(['Units: $\\hbar=c=1$; masses and inverse lengths in GeV; $\\hbar c=1.973269804\\times10^{-16}$ GeV m (Mathematica `tbHbarCm`).',
          'Coordinates $X=(x_0,x_1,\\dots,x_7)$ (Mathematica `X` $=$ `{x0, …, x7}`): $x_0$ is time (the direction of the octonion unit $e_0=1$), '
          '$x_1,x_2,x_3$ ordinary space, $x_4,\\dots,x_7$ the four extra space-like coordinates: on the 4-torus periodic with period $L_c$, on the '
          '4-sphere the angles $x_4,x_5,x_6\\in[0,\\pi]$, $x_7\\in[0,2\\pi)$.',
          'Indices: $A,B=0,\\dots,7$; $\\mu,\\nu=0,\\dots,3$ (ordinary spacetime, the directions of the world brane); $i,j=4,\\dots,7$ (the extra '
          'space); $a,b=1,\\dots,4$ (frame indices of the extra space, or the coordinates $X_a$ of $\\mathbb R^5$ when $a,b\\le5$). A prime is $d/dx_0$ '
          '(cosmology) or $d/dy$ (warped metrics); $\\ln$ is the natural logarithm.',
          'Curvature (mostly-minus signature): $R^\\rho{}_{\\sigma\\mu\\nu}=\\partial_\\mu\\Gamma^\\rho{}_{\\nu\\sigma}-\\partial_\\nu\\Gamma^\\rho{}_{\\mu\\sigma}+\\Gamma^\\rho{}_{\\mu\\lambda}\\Gamma^\\lambda{}_{\\nu\\sigma}'
          '-\\Gamma^\\rho{}_{\\nu\\lambda}\\Gamma^\\lambda{}_{\\mu\\sigma}$, $R_{\\sigma\\nu}=R^\\rho{}_{\\sigma\\rho\\nu}$, $R=g^{\\sigma\\nu}R_{\\sigma\\nu}$, $G^A{}_B=R^A{}_B-\\frac12\\delta^A_BR$; field '
          'equations $G^A{}_B-\\Lambda\\delta^A_B=\\kappa T^A{}_B$.'])
    signature_block(d, eta=r'\eta', eta71=r'\eta_{71}', gam=r'\Gamma')

    # ------------------------------------------------------------------------------------------------
    d.h1('2. Coordinates, metrics and the two extra spaces')
    d.table(HEAD4, [
        ['$x$, $y$', '`{x0, …, x3}`, `{x4, …, x7}`', '$x=(x_0,\\dots,x_3)$, $y=(x_4,\\dots,x_7)$', 'a point of ordinary spacetime; a point of the extra space'],
        ['$G_{AB}$, $ds^2$', '—', '(2.1)', 'the eight-dimensional metric of the radion ansatz'],
        ['$g_{E\\mu\\nu}$', '`{rdLp^2, -rdSa^2, …}` (homogeneous)', '(2.1)', 'the four-dimensional Einstein-frame metric'],
        ['$N$, $a$', '`rdLp[x0]`, `rdSa[x0]`', '$g_E=\\mathrm{diag}(N^2,-a^2,-a^2,-a^2)$', 'lapse and scale factor of the homogeneous checks'],
        ['$\\gamma_{ij}$', '`rdB0^2 {1,1,1,1}`, `rdR0^2 rdGam4`', '$b_0^2\\delta_{ij}$ ($T^4$); $r_0^2\\hat\\gamma_{ij}$ ($S^4$)', 'the fixed reference metric of the extra space'],
        ['$\\hat\\gamma$', '`rdGam4`', '(2.2)', 'the metric of the unit 4-sphere'],
        ['$T^4$', '—', '$\\mathbb R^4/(L_c\\mathbb Z)^4$', 'the 4-torus (the auxiliary space of 7+1.nb)'],
        ['$S^4$', '—', '(2.3)', 'the 4-sphere (for comparison)'],
        ['$L_c$', '`rdLc`', 'coordinate period', 'period of each torus coordinate'],
        ['$b$, $b_0$', '`b4[x0]` (section 11), `rdB0`', '$b=b_0e^\\beta$', 'size of the torus; its reference value'],
        ['$r$, $r_0$', '`rdR0` ($r_0$)', '$r=r_0e^\\beta$', 'radius of the sphere; its reference value'],
        ['$V$, $V_0$', '`v0` (argument of `rdMini`)', '(2.4)', 'proper volume of the extra space; at $\\beta=0$'],
        ['$V_\\perp$, $\\ell_\\perp$', '`rIIVp`, `tbLp`', '$V_\\perp=M_{\\rm Pl}^2/M_8^6$, $\\ell_\\perp=V_\\perp^{1/4}$', 'volume of the torus today; its proper period'],
        ['$r_{S^4}$', '`rdRS4`', '$(3V_\\perp/(8\\pi^2))^{1/4}$', 'radius of a sphere with the volume $V_\\perp$'],
        ['$X_a$', '`rdEmb`', '(2.3)', 'embedding of $S^4$ in $\\mathbb R^5$, $a=1,\\dots,5$'],
        ['$R_{\\rm int}$', '`rint` (argument of `rdMini`)', '$0$ ($T^4$), $12/r^2$ ($S^4$)', 'scalar curvature of the extra space itself (positive for the sphere)'],
        ['$R$, $R_E$', '`rdScal[g, X]`', 'section 1', 'scalar curvature of $G$; of $g_E$'],
        ['$R_{ij}$', '`rdRic`, `rdRicS4`', 'section 1', 'Ricci tensor'],
    ], widths=W4, small=True)
    d.align([r'ds^2&=G_{AB}dX^AdX^B=e^{-4\beta(x)}g_{E\mu\nu}(x)dx^\mu dx^\nu-e^{2\beta(x)}\gamma_{ij}(y)dy^idy^j,&&(2.1)',
             r'\hat\gamma&=\mathrm{diag}\big(1,\ \sin^2x_4,\ \sin^2x_4\sin^2x_5,\ \sin^2x_4\sin^2x_5\sin^2x_6\big),&&(2.2)',
             r'X_a&=r\,\big(\sin x_4\sin x_5\sin x_6\cos x_7,\ \sin x_4\sin x_5\sin x_6\sin x_7,\ \sin x_4\sin x_5\cos x_6,\ \sin x_4\cos x_5,\ \cos x_4\big),&&(2.3)',
             r'V&=\int d^4y\sqrt{\det(e^{2\beta}\gamma)}=V_0e^{4\beta},\qquad V_0=b_0^4L_c^4\ (T^4),\quad V_0=\frac{8\pi^2}3r_0^4\ (S^4).&&(2.4)'])

    # ------------------------------------------------------------------------------------------------
    d.h1('3. The radion, the Einstein frame and the reduced action')
    d.table(HEAD4, [
        ['$\\beta$', '`rdBt[x0]` (field), `rdBe` (number)', '$\\ln(b/b_0)$ or $\\ln(r/r_0)$', 'the radion (dimensionless)'],
        ['$\\phi$', '—', '(3.1)', 'the canonical radion (mass dimension 1)'],
        ['$\\alpha$, $\\beta$ (the note)', '—', '$ds^2=e^{2\\alpha\\phi}g+e^{2\\beta\\phi}\\gamma$', 'the constants of the note’s ansatz; $\\beta\\phi$ of the note is our $\\beta(x)$'],
        ['$\\beta_n$', '—', '(3.3)', 'the constant $\\beta$ for $n$ extra dimensions'],
        ['$\\varphi$', '`rdPh[x0]`', '$\\beta=\\beta_n\\varphi$', 'the radion in the normalization of the note (dimensionless)'],
        ['$n$', '`n` in `rdKinOK`, `rdKinC`', '$D=4+n$', 'number of extra dimensions'],
        ['$c_n$', '`rdKinC[n]`, `rdKinCs`', '(3.2)', 'coefficient of the radion kinetic term'],
        ['$\\kappa$', '`rdKap`', '$8\\pi G_8=M_8^{-6}$', 'eight-dimensional gravitational coupling'],
        ['$M_8$', '`rIIM8`', '10 TeV', 'eight-dimensional Planck scale of the examples'],
        ['$M_{\\rm Pl}$', '`rIIMPl`, `rdMP2` ($M_{\\rm Pl}^2$)', '(3.1)', 'reduced four-dimensional Planck mass, $2.435\\times10^{18}$ GeV'],
        ['$G_4$, $G_8$', '—', '$8\\pi G_4=M_{\\rm Pl}^{-2}$, $8\\pi G_8=\\kappa$', 'Newton constants'],
        ['$\\Lambda$', '`rdLam`', 'section 1', 'bulk cosmological constant ($\\Lambda>0$: de Sitter)'],
        ['$U$, $U_0$, $U_1$, $K_U$', '`rdU`, `rdU0`, `rdU1`, `rdKU`, `rdUq`', '(4.1)', 'stabilizing energy density of the bulk and its expansion'],
        ['$S$', '—', '(3.4)', 'the action'],
        ['$\\Omega$', '`rdOmg`, `rdOmE`', '$h=\\Omega^2\\eta$', 'conformal factor (section 6)'],
    ], widths=W4, small=True)
    d.align([r'\phi&=\sqrt{12}\,M_{\rm Pl}\,\beta,\qquad M_{\rm Pl}^2=\frac{V_0}\kappa,\qquad 6M_{\rm Pl}^2(\partial\beta)^2=\frac12(\partial\phi)^2,&&(3.1)',
             r'-\frac1{2\kappa}\int d^ny\sqrt{|G|}R&=\sqrt{|g_E|}\Big[-\frac{M_{\rm Pl}^2}2R_E+\frac{M_{\rm Pl}^2}2c_n(\partial\beta)^2\Big]+\text{(total derivative)},&&(3.2)',
             r'c_n&=\frac{n(n+2)}2,',
             r'2\alpha+n\beta_n&=0;\qquad\text{the note: }\beta_n=\sqrt{\frac2{n(n+2)}}\ \ (c_n\beta_n^2=1);&&(3.3)',
             r'&\qquad\text{canonical: }\beta_n=\frac1{\sqrt{n(n+2)}}\ \ (c_n\beta_n^2=\tfrac12),',
             r'S&=-\frac1{2\kappa}\int d^8X\sqrt{|G|}(R+2\Lambda)-\int d^8X\sqrt{|G|}\,U+S_{\rm brane}+S_{\rm matter}.&&(3.4)'])

    # ------------------------------------------------------------------------------------------------
    d.h1('4. The potential and the mass')
    d.table(HEAD4, [
        ['$V(\\beta)$', '`rdV[curv, flux]`', '(4.2)', 'Einstein-frame potential of the radion'],
        ['$\\sigma$', '`curv` (argument of `rdV`)', '$0$ ($T^4$), $1$ ($S^4$)', 'switch of the curvature term'],
        ['$F$, $\\rho_F$, $q$', '`rdFx`, `rdRhoF`, `rdQ2` ($q^2$)', '(4.3)', 'flux term; flux energy density; flux quantum (illustration)'],
        ['$W(a,b)$', 'argument of `feStress`', '(4.3)', 'comoving energy of a source'],
        ['$\\varepsilon$, $p_a$, $p_b$', '`rdEps`, `rdPa`, `rdPb`', '(4.3)', 'energy density, pressures along ordinary and extra space'],
        ['$H_a$, $H_b$', '`Ha`, `Hb` (section 20)', '$a\'/a$, $b\'/b$', 'expansion rates; $H_b=\\beta\'$'],
        ['$m_r$, $m_r^2$', '`rdM2L` (Λ-only case)', '(4.4)', 'mass of the radion (10 GeV in the examples of 7+1.nb)'],
        ['$H$', '`rdHE2` ($H^2$)', '$H^2=V(0)/(3M_{\\rm Pl}^2)$', 'Hubble rate of four-dimensional de Sitter space'],
        ['$\\Phi$, $m_8$', '`rdPhi[x4, x5]`, `rdMm`', '(4.5)', 'a bulk scalar and its mass (the note’s stabilizer)'],
    ], widths=W4, small=True)
    d.align([r'U(\beta)&=U_0+U_1\beta+\frac{K_U}2\beta^2,&&(4.1)',
             r'V(\beta)&=M_{\rm Pl}^2\Big[e^{-4\beta}\big(\Lambda+\kappa U(\beta)\big)-\frac{6\sigma}{r_0^2}e^{-6\beta}+F\,e^{-12\beta}\Big],&&(4.2)',
             r'\varepsilon&=\frac W{a^3b^4},\quad p_a=-\frac{\partial_aW}{3a^2b^4},\quad p_b=-\frac{\partial_bW}{4a^3b^3};\qquad W=\frac{a^3b^4q^2}{2b^8}:\ \rho_F=\frac{q^2}{2b^8},\ F=\kappa\rho_F(b_0),&&(4.3)',
             r"m_r^2&=\frac{d^2V}{d\phi^2}\Big|_0=\frac{V''(0)}{12M_{\rm Pl}^2},&&(4.4)",
             r'&\sqrt{|G|}\Big(\frac12G^{AB}\partial_A\Phi\partial_B\Phi-\frac12m_8^2\Phi^2\Big)=-\sqrt{|g_E|}\sqrt\gamma\,e^{-4\beta}\Big(\frac12e^{-2\beta}|\nabla\Phi|_\gamma^2+\frac12m_8^2\Phi^2\Big).&&(4.5)'])

    # ------------------------------------------------------------------------------------------------
    d.h1('5. The radion and the world brane')
    d.table(HEAD4, [
        ['$W$ (brane)', '—', '$y=0$ ($T^4$), $x_4=0$ ($S^4$)', 'the world brane'],
        ['$h_{\\mu\\nu}$', '—', '(5.1)', 'induced metric on the brane'],
        ['$T^\\mu{}_\\mu$', '—', 'trace of $T^{\\mu\\nu}$', 'trace of the energy–momentum tensor of brane matter'],
        ['$M$, $M\'$', '`rdMs`', 'masses', 'point masses on the brane'],
        ['$g$', '—', '(5.2)', 'coupling of the radion to $T^\\mu{}_\\mu$'],
        ['$\\alpha$ (fifth force)', '—', '(5.2)', 'strength of the radion force relative to gravity'],
        ['$\\lambda$ (Yukawa)', '—', '$1/m_r$', 'range of a Yukawa force'],
        ['$r$ (distance)', '—', '$|\\vec x-\\vec x\\,\'|$', 'distance between two masses'],
    ], widths=W4, small=True)
    d.align([r'h_{\mu\nu}&=e^{-4\beta}g_{E\mu\nu}\quad(n=4;\ \text{in general }e^{-n\beta}g_{E\mu\nu}),&&(5.1)',
             r'\mathcal L_{\rm int}&=g\,\phi\,T^\mu{}_\mu,\quad g=\frac1{\sqrt3M_{\rm Pl}}\ \Big(\text{in general }\frac1{M_{\rm Pl}}\sqrt{\frac n{2(n+2)}}\Big),\quad \alpha=2(gM_{\rm Pl})^2=\frac n{n+2}.&&(5.2)'])

    # ------------------------------------------------------------------------------------------------
    d.h1('6. The Higgs boson and the radion')
    d.table(HEAD4, [
        ['$H$, $\\varphi_H$', '`rdPhE` ($\\varphi_H$)', '$H^\\dagger H=\\varphi_H^2/2$, $\\varphi_H=v+h$', 'Higgs doublet; its radial field'],
        ['$v$', '`vEW`, `rdVv`', '$(\\sqrt2G_F)^{-1/2}=246.22$ GeV', 'Higgs vacuum value'],
        ['$h$, $r$', '`rdHh[x0, x1]`, `rdRr[x0, x1]`', 'section 6', 'bare Higgs and radion fields (canonical $r$)'],
        ['$\\lambda$ (Higgs)', '`rdLamH`', '$V=\\frac\\lambda4(\\varphi_H^2-v^2)^2$', 'Higgs quartic coupling'],
        ['$\\xi$', '`rdXi`', '(6.1)', 'curvature coupling of the Higgs ($\\frac16$: conformal)'],
        ['$\\Lambda_r$, $\\gamma$', '`rdO1` ($1/\\Lambda_r$), `rdGam`', '$\\Omega=1+r/\\Lambda_r+\\dots$, $\\gamma=v/\\Lambda_r$', 'coupling scale of the radion; mixing parameter'],
        ['$m_{h0}$, $m_{r0}$', '`rdMh0`, `rdMr0`', '$m_{h0}^2=2\\lambda v^2$', 'bare Higgs and radion masses'],
        ['$c$', '`rdc4`', '(6.2)', 'coefficient of $\\Omega\\Box\\Omega$'],
        ['$K$, $K_{hr}$, $K_{rr}$', '`rdKm`, `rdKhr`, `rdKrr`', '(6.3)', 'kinetic matrix of $(h,r)$'],
        ['$S$ (shift), $Z$', '`rdSm`, `rdZ`, `rdZ2` ($Z^2$)', '(6.4)', 'kinetic shift; normalization'],
        ['$M\'$', '`rdMp`', '(6.5)', 'mass matrix of $(h\',r\')$'],
        ['$Q(\\theta)$, $\\theta$', '`rdQ[th]`, `rdth`', '(6.5)', 'rotation; mixing angle'],
        ['$h_m$, $r_m$', '—', '(6.5)', 'mass eigenstates'],
        ['$C_h$, $C_r$', '—', '(6.5)', 'coefficients of $h_m$ in $h$ and $r$'],
        ['$b_{\\rm EM}$, $F_{\\rm SM}$, $b_{\\rm QCD}$, $F_{\\rm heavy}$', '—', '$-\\frac{11}3$, $-6.5$, $7$, $-\\frac43$ (the note)', 'trace-anomaly and loop coefficients'],
        ['$\\Gamma$', '`rdHRnum`, `rdHR71`', '(6.6)', 'decay rates of the Higgs boson'],
    ], widths=W4, small=True)
    d.align([r'\mathcal L&=\sqrt{|h|}\Big[\frac12h^{\mu\nu}\partial_\mu\varphi_H\partial_\nu\varphi_H-\frac\lambda4(\varphi_H^2-v^2)^2+\frac\xi2R(h)\varphi_H^2\Big]+\frac12(\partial r)^2-\frac12m_{r0}^2r^2,&&(6.1)',
             r'h&=\Omega^2\eta:\quad \sqrt{|h|}R(h)=c\,\Omega\Box\Omega,\quad c=-6,\quad \Box=\partial_0^2-\nabla^2,&&(6.2)',
             r'\mathcal L^{(2)}&=\frac12\begin{pmatrix}\partial h&\partial r\end{pmatrix}K\begin{pmatrix}\partial h\\ \partial r\end{pmatrix}-\frac12m_{h0}^2h^2-\frac12m_{r0}^2r^2,\quad K=\begin{pmatrix}1&6\xi\gamma\\ 6\xi\gamma&1+6\xi\gamma^2\end{pmatrix},&&(6.3)',
             r"\begin{pmatrix}h\\ r\end{pmatrix}&=S\begin{pmatrix}h'\\ r'\end{pmatrix},\quad S=\begin{pmatrix}1&-6\xi\gamma/Z\\ 0&1/Z\end{pmatrix},\quad S^{\mathsf T}KS=1\iff Z^2=1+6\xi\gamma^2(1-6\xi),&&(6.4)",
             r"M'&=S^{\mathsf T}\mathrm{diag}(m_{h0}^2,m_{r0}^2)S,\quad \begin{pmatrix}h'\\ r'\end{pmatrix}=Q(\theta)\begin{pmatrix}h_m\\ r_m\end{pmatrix},\quad Q(\theta)=\begin{pmatrix}\cos\theta&-\sin\theta\\ \sin\theta&\cos\theta\end{pmatrix},&&(6.5)",
             r"&\tan2\theta=\frac{12\gamma\xi Zm_{h0}^2}{m_{r0}^2-m_{h0}^2(Z^2-36\xi^2\gamma^2)},\quad C_h=\cos\theta-\frac{6\xi\gamma}Z\sin\theta,\quad C_r=\frac{\sin\theta}Z,",
             r'\frac{\Gamma(h\to\gamma\gamma)}{\Gamma_{\rm SM}}&=\Big|C_h+C_r\gamma\frac{b_{\rm EM}}{F_{\rm SM}}\Big|^2,\qquad \frac{\Gamma(h\to gg)}{\Gamma_{\rm SM}}=\Big|C_h+C_r\gamma\frac{b_{\rm QCD}}{F_{\rm heavy}}\Big|^2.&&(6.6)'])

    # ------------------------------------------------------------------------------------------------
    d.h1('7. Kaluza–Klein levels on $T^4$ and $S^4$')
    d.table(HEAD4, [
        ['$\\Psi$, $\\psi_n$, $Y_n$', '—', '$\\Psi=\\sum_n\\psi_n(x)Y_n(y)$', 'a bulk field, its four-dimensional modes and the eigenfunctions'],
        ['$\\Delta_\\gamma$', '—', 'Laplacian of $\\gamma$', 'Laplacian of the extra space'],
        ['$\\mu$, $\\mu_n$', '—', '$-\\Delta_\\gamma Y_n=\\mu_n^2Y_n$', 'Kaluza–Klein mass'],
        ['$\\vec n$, $k$', '—', '$\\vec n\\in\\mathbb Z^4$, $k=|\\vec n|^2$', 'torus mode number; shell'],
        ['$r_4(k)$, $\\sigma(k)$', '`rIIr4`, `rIIsig`', '(7.1)', 'number of $\\vec n$ with $|\\vec n|^2=k$; divisor sum'],
        ['$l$, $d_l$', '`rdDl[l]`', '(7.2)', 'degree of a spherical harmonic; multiplicity'],
        ['$N(\\mu)$, $x$, $L$, $y$', '`rdNS4[x]`, `rdWeyl`', '(7.3)', 'number of states below $\\mu$; $x=\\mu r$; largest $l$; $y=L+2$'],
        ['$Z_l$, $C_l^{(3/2)}$', '`rdZon[l]`, `GegenbauerC`', '(7.4)', 'zonal harmonic; Gegenbauer polynomial'],
        ['$L_{ab}$', '—', '$X_a\\partial_b-X_b\\partial_a$', 'rotations of $\\mathbb R^5$ (Killing vectors of $S^4$)'],
    ], widths=W4, small=True)
    d.align([r'r_4(k)&=8\sigma(k)-32\sigma(k/4),\quad \sigma(k)=\sum_{d|k}d\ (\sigma(k/4)=0\text{ unless }4|k);\quad T^4:\ \mu=\frac{2\pi|\vec n|}{\ell_\perp},&&(7.1)',
             r'S^4:\ \mu&=\frac{\sqrt{l(l+3)}}r,\quad d_l=\frac{(2l+3)(l+1)(l+2)}6=\binom{l+4}4-\binom{l+2}4,&&(7.2)',
             r'N(\mu)&\simeq\frac{V\mu^4}{32\pi^2};\quad S^4:\ N=\sum_{l\le L}d_l=\frac{y^2(y^2-1)}{12},\quad L(L+3)\le x^2<(L+1)(L+4),&&(7.3)',
             r'Z_l(x_4)&=\sqrt{\frac{d_l}V}\,\frac{C_l^{(3/2)}(\cos x_4)}{C_l^{(3/2)}(1)},\qquad C_l^{(3/2)}(1)=\frac{(l+1)(l+2)}2.&&(7.4)'])

